def build(index: int, item: tuple) -> dict:
    answer, source_key, skill, prompt, options, explanation, steps, locator, observed = item
    url, title, year = SOURCES[source_key]
    return {
        "id": f"question-english-performance-2-iv-14-{index}",
        "subject": "english", "type": "single-choice", "prompt": prompt,
        "options": [{"id": chr(65 + pos), "text": option} for pos, option in enumerate(options)],
        "knowledgeIds": ["kg-english-performance-2-iv-14"], "difficulty": "medium",
        "answer": {"value": answer, "explanation": explanation + f" 正確答案：{answer}。"},
        "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": url, "sourceLocator": locator + "；情境、語句、選項、正解與解析皆重新創作。", "authoringNote": "僅參考公立學校英文試題中的文化閱讀、表格比對、證據推論與節慶資訊題型作pattern-only改寫，未複製原題、選項、圖表或答案。"},
        "reviewStatus": "draft", "updatedAt": "2026-09-24", "lessonId": "lesson-english-performance-2-iv-14",
        "examPatternRefs": [{"url": url, "title": title + "；僅參考文化閱讀或資訊判讀能力，不複製原卷內容。", "year": year, "subject": "english", "locator": locator, "observedPattern": observed, "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "item"}],
        "solutionStrategy": f"{skill}：先找來源中可以直接核對的線索，再比較選項主張的範圍是否超出證據。",
        "solutionSteps": steps,
    }


for number, item in enumerate(ITEMS, 1):
    (OUT / f"question-english-performance-2-iv-14-{number}.json").write_text(json.dumps(build(number, item), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(ITEMS)} original culture-literacy questions")
